List<int> parseNestedParens(String parenString) {
  List<int> result = [];

  void parseParenGroup(int depth, int startIdx) {
    if (depth <= 0 || startIdx >= parenString.length) return;

    String group = '';
    for (int i = startIdx; i < parenString.length && parenString[i] != ')'; ++i) {
      group += parenString[i];
    }
    if (group.isEmpty) return; // invalid or no closing

    result.add(depth);
    parseParenGroup(depth - 1, group.indexOf('('));
  }

  final groups = parenString.split('()').where((s) => s.isNotEmpty).toList();
  for (final g in groups) {
    parseParenGroup(groups.length + 1, g.indexOf('('));
  }
  return result;
}

