List<double> findClosestElements(List<double> numbers) {
  List<double>? closestPair;
  double? distance;

  for (int idx = 0; idx < numbers.length; idx++) {
    double elem = numbers[idx];
    for (int idx2 = 0; idx2 < numbers.length; idx2++) {
      double elem2 = numbers[idx2];
      if (idx != idx2) {
        if (distance == null) {
          distance = (elem - elem2).abs();
          closestPair = [elem, elem2]..sort();
        } else {
          double newDistance = (elem - elem2).abs();
          if (newDistance < distance) {
            distance = newDistance;
            closestPair = [elem, elem2]..sort();
