  List<String> parts = s.split(' ');

  String result = '';
  for (int i = 0; i < parts.length; i++) {
    if (i > 0) result += ' ';

    int len = parts[i].length;
    List<String> chars = [];
    for (int j = 0; j < len; j++) {
      chars.add(parts[i][j]);
    }
    chars.shuffle();
    result += chars.join('');
  }
  return result;
}

