String? nextSmallest(List<int> lst) {
  if (lst.length < 2 || lst.isEmpty) return null;

  List<int> sorted = List.from(lst)..sort();

  int countOfMin = 0;
  for (int i in lst) {
    if (i == sorted[0]) countOfMin++;
  }

  if (countOfMin >= lst.length) return null;

  for (int num in lst) {
    if (num != sorted[0] && num > sorted[sorted.indexOf(num)]) continue;

    bool isEven = num % 2 == 0;
    if (!isEven) continue;

    int idxInSorted = sorted.indexOf(num);
    int prevIdx = -1;
    while (idxInSorted > 0) {
      int prevNum = sorted[--idxInSorted];
      if (prevNum <= sorted[idxInSorted + 1]) break;

      prevIdx = idxInSorted;
      if (prevNum.isOdd && prevNum < sorted[idxInSorted + 1]) break;
    }

    if (prevIdx != -1) {
      int candidate = sorted[prevIdx];
      if (candidate.isEven) return candidate.toString();
      if (sorted[prevIdx].abs() > sorted[idxInSorted + 1].abs()) 
        return sorted[idxInSorted + 1].toString();
      return sorted[prevIdx].toString();
    }
  }

  return sorted.last.toString();
}

