int maxFill(List<List<int>> grid, int capacity) {
  final n = grid.length;
  if (n == 0 || n > capacity * 2) return 0;

  final directions = [
    (-1, 0), // up
    (1, 0),  // down
    (0, -1), // left
    (0, 1),  // right
  ];

  List<bool> visited = List.filled(n, false);

  void dfs(int row, int col, int area) {
    if (row < 0 || row >= n || col < 0 || col >= n || 
        !grid[row][col] || visited[row]) {
      return;
    }

    visited[row] = true;
    for (final dir in directions) {
      final newRow = row + dir[0];
      final newCol = col + dir[1];

      if (!visited[newRow] && newRow >= 0 && newRow < n && 
          newCol >= 0 && newCol < n && grid[newRow][newCol]) {
        dfs(newRow, newCol, area + 1);
      }
    }
  }

  int best = 0;
  while (best <= capacity) {
    filled: for (var i = 0; i < n; i++) {
      for (var j = 0; j < n; j++) {
        if (!visited[i] && grid[i][j]) {
          dfs(i, j, 0);

          var totalArea = 0;
          for (var k = 0; k < n; k++) {
            for (var l = 0; l < n; l++) {
              if (visited[k] && grid[k][l]) totalArea++;
            }
          }

          if (totalArea % 2 != 0) break filled;
          best += 4;
        }
      }
    }

    if (best >= capacity) return capacity;
  }

  return best;
}

