List<String> sortedListSum(List<String> lst) {
  if (lst.length <= 1) return [];

  List<String> copy = List.from(lst);
  copy.sort((a, b) => a.compareTo(b));

  var stack = <String>[];
  for (var i = 0; i < copy.length - 1; i++) {
    String current = copy[i];
    String next = copy[i + 1];

    if (current == next || !current.contains(next)) continue;

    int minIdx = current.indexOf(next);
    int maxIdx = current.lastIndexOf(next);

    if ((maxIdx - minIdx) % 2 != 0) continue;

    String sub = current.substring(minIdx, maxIdx + 1);
    if (!sub.contains(current[0])) continue;

    bool isOddCount = false;
    for (int j = 0; j < sub.length; j += 2) {
      if (j + 1 >= sub.length) break;
      if (sub[j] != sub[j + 1]) continue;
      if (isOddCount && j > 0 && sub[j - 1] != sub[j]) continue;
      isOddCount = true;
    }

    if (!isOddCount) continue;

    stack.add(sub);
  }

  return stack.reversed.toList();
}

