String strongestExtension(String className, List<String> extensions) {
  if (extensions.isEmpty) return className;

  final sorted = extensions
      .map((e) => e.split('').reversed.join()) // reverse characters
      .toList()
    ..sort();

  int count = sorted[sorted.length - 1].length;

  for (int i = sorted.length - 2; i >= 0; i--) {
    String s = sorted[i];
    bool sameCountAndFirstCharAsLast = s.length == count && s[s.length - 1] == sorted[sorted.length - 1][s.length - 1];
    if (!sameCountAndFirstCharAsLast) break;
    count++;
  }

  final filtered = extensions.where((ext) {
    final reversed = ext.split('').reversed.join();
    return reversed.length >= count && reversed[count - 1] == 'A';
  }).toList();

  final result = filtered.isNotEmpty ? filtered.first : '';
  return '$className.$result';
}

