String solve(String s) {
  int flg = 0;
  int idx = 0;
  List<String> newStr = s.split('');

  for (int i = 0; i < s.length; i++) {
    String char = s[i];
    if (RegExp(r'[a-zA-Z]').hasMatch(char)) {
      if (char == char.toUpperCase()) {
        newStr[idx] = char.toLowerCase();
      } else {
        newStr[idx] = char.toUpperCase();
      }
      flg = 1;
    }
    idx++;
  }

  String result = newStr.join('');

  if (flg == 0) {
    return result.split('').reversed.join('');
  }
  return result;
}

@pragma('vm:entry-point')
void main() {
  print(solve("1234"));
  print(solve("ab"));
  print(solve("#a@C"));
  print(solve(""));
  print(solve("ABC"));
  print(solve("123#@!"));
}

